with extra as (
  select * from jsonb_to_recordset($content$[
    {"day":4,"level":"A1","questions":[{"type":"mcq","question":"Which foods are named in the text?","options":["Rice, beans, fish and vegetables","Only bread and cakes","Tea and coffee","Sweets and biscuits"],"answer":"Rice, beans, fish and vegetables","explanation_fr":"Le texte cite le riz, les haricots, le poisson et les légumes."},{"type":"true_false","question":"Sleep is important for your body.","options":["True","False"],"answer":"True","explanation_fr":"Le dernier paragraphe indique que le sommeil est important pour le corps."},{"type":"mcq","question":"Which activity is suggested in the text?","options":["Dancing","Driving all day","Sleeping at school","Skipping meals"],"answer":"Dancing","explanation_fr":"Marcher, danser et jouer au football sont les activités proposées."},{"type":"mcq","question":"What kind of water should you drink?","options":["Safe water","Only sparkling water","Only sweet water","No water"],"answer":"Safe water","explanation_fr":"Le texte recommande de boire de l'eau potable chaque jour."},{"type":"open","question":"What small healthy change can you choose today?","options":[],"answer":"I can drink safe water regularly, eat different foods, take a short walk or go to bed at a regular time.","explanation_fr":"La réponse doit proposer une petite action concrète et réaliste parmi celles du texte."}]},
    {"day":4,"level":"A2","questions":[{"type":"mcq","question":"Which foods give you energy, according to the text?","options":["Rice and cassava","Only fruit","Only sweets","Water and soap"],"answer":"Rice and cassava","explanation_fr":"Le texte indique que le riz et le manioc donnent de l'énergie."},{"type":"mcq","question":"Which foods help your body grow and repair itself?","options":["Beans, eggs and fish","Rice and water","Fruit and cassava","Sweet drinks"],"answer":"Beans, eggs and fish","explanation_fr":"Les haricots, les œufs et le poisson aident le corps à grandir et à se réparer."},{"type":"true_false","question":"Fruit and vegetables provide vitamins.","options":["True","False"],"answer":"True","explanation_fr":"Le texte précise que les fruits et légumes apportent des vitamines."},{"type":"mcq","question":"Do you need a gym to move your body?","options":["No, walking and dancing also count","Yes, always","Only on weekends","Only for football players"],"answer":"No, walking and dancing also count","explanation_fr":"La marche, la danse et le football sont proposés comme activités accessibles."},{"type":"open","question":"Which small action will you repeat each day?","options":[],"answer":"I can carry safe drinking water, eat a variety of foods, take a walk or keep a regular bedtime.","explanation_fr":"La réponse doit choisir une action simple pouvant devenir une habitude."}]},
    {"day":4,"level":"B1","questions":[{"type":"mcq","question":"Why is water usually a better everyday choice than sweet drinks?","options":["Sweet drinks can contain a lot of sugar","Water has a bright colour","Sweet drinks are always hot","Water replaces all meals"],"answer":"Sweet drinks can contain a lot of sugar","explanation_fr":"Le texte mentionne la forte teneur en sucre possible des boissons sucrées."},{"type":"true_false","question":"If you sit for a long time, you should get up and move regularly.","options":["True","False"],"answer":"True","explanation_fr":"Le texte conseille de se lever et de bouger régulièrement après une longue position assise."},{"type":"mcq","question":"What example of an easy repeatable goal is given?","options":["Putting safe water in your bag each morning","Buying a gym membership every day","Changing your whole routine at once","Avoiding all housework"],"answer":"Putting safe water in your bag each morning","explanation_fr":"Préparer une bouteille d'eau potable chaque matin est l'exemple donné."},{"type":"mcq","question":"Which meal best matches the text?","options":["Vegetables, beans and rice","Only a sweet drink","Only cassava every day","No food at all"],"answer":"Vegetables, beans and rice","explanation_fr":"Ce repas associe plusieurs catégories d'aliments citées dans le texte."},{"type":"open","question":"What realistic healthy goal can you connect to an existing routine?","options":[],"answer":"After preparing my bag, I can add a bottle of safe drinking water for the next day.","explanation_fr":"La réponse doit relier une action santé réaliste à une habitude déjà présente."}]},
    {"day":4,"level":"B2","questions":[{"type":"mcq","question":"What does friction mean in this text?","options":["The effort required to begin an action","A physical injury from walking","The price of fresh food","A disagreement about health"],"answer":"The effort required to begin an action","explanation_fr":"Le texte définit la friction comme l'effort nécessaire pour commencer une action."},{"type":"true_false","question":"Changing your surroundings can reduce the number of decisions you must make.","options":["True","False"],"answer":"True","explanation_fr":"Les changements de l'environnement réduisent les décisions, sans supprimer tout effort."},{"type":"mcq","question":"What does the text say about the time needed to build a habit?","options":["It varies between people and habits","It is always exactly one week","It is identical for everyone","It never requires repetition"],"answer":"It varies between people and habits","explanation_fr":"Le texte précise que le temps nécessaire varie selon les personnes et les habitudes."},{"type":"mcq","question":"Which factors should a realistic healthy choice consider?","options":["Budget, schedule and local conditions","Only motivation","Only other people's routines","Only expensive equipment"],"answer":"Budget, schedule and local conditions","explanation_fr":"Ces trois facteurs sont explicitement cités dans le texte."},{"type":"open","question":"How could you reduce friction for one healthy action in your own day?","options":[],"answer":"I can prepare my walking shoes and safe drinking water before I need them, so starting requires less effort.","explanation_fr":"La réponse doit décrire une préparation concrète qui facilite le début de l'action."}]},
    {"day":4,"level":"C1","questions":[{"type":"true_false","question":"The text argues that supportive surroundings can complement personal intention.","options":["True","False"],"answer":"True","explanation_fr":"Le texte présente l'environnement comme un soutien à l'intention, et non comme son remplacement."},{"type":"mcq","question":"Which statement is an implementation intention?","options":["When I finish dinner, I will prepare my water bottle","I will try to be healthier somehow","I must never make a mistake","Other people should organise my day"],"answer":"When I finish dinner, I will prepare my water bottle","explanation_fr":"Cette phrase relie une situation précise à une réponse prévue."},{"type":"mcq","question":"Why is repeatedly blaming yourself an unhelpful response to a failed routine?","options":["The routine may need a more realistic design","Failure proves that change is impossible","External conditions never matter","Intentions are always sufficient"],"answer":"The routine may need a more realistic design","explanation_fr":"Une routine qui échoue peut devoir être repensée au lieu de provoquer un jugement plus sévère."},{"type":"mcq","question":"What is the most balanced interpretation of the text?","options":["Personal choices matter, but practical conditions also shape them","Environment determines every action","Willpower is the only relevant factor","Healthy routines must be identical for everyone"],"answer":"Personal choices matter, but practical conditions also shape them","explanation_fr":"L'argument associe responsabilité personnelle et conditions pratiques."},{"type":"open","question":"Redesign one routine using a specific cue and a realistic response.","options":[],"answer":"When I close my notebook at night, I will place my water bottle beside my bag. This links a clear cue to an action that fits my routine.","explanation_fr":"La réponse doit formuler un déclencheur identifiable, une action réaliste et leur lien."}]},
    {"day":5,"level":"A1","questions":[{"type":"mcq","question":"Which items are on Ada's list?","options":["Books, pen and water","Shoes, rice and fish","A guitar and a ball","Keys, soap and fruit"],"answer":"Books, pen and water","explanation_fr":"La liste d'Ada contient les livres, le stylo et l'eau."},{"type":"true_false","question":"Ada checks her bag after reading her list.","options":["True","False"],"answer":"True","explanation_fr":"Elle lit sa liste puis vérifie son sac."},{"type":"mcq","question":"Where else can you use a list, according to the text?","options":["For shopping","Only at school","Only during a football match","Only at work"],"answer":"For shopping","explanation_fr":"Le texte propose une liste pour l'école, le travail ou les courses."},{"type":"mcq","question":"When can this habit help you?","options":["When you get ready for the next day","Only when you sleep","Only when you eat","When you lose every list"],"answer":"When you get ready for the next day","explanation_fr":"Cette petite habitude aide à préparer la journée suivante."},{"type":"open","question":"What would you write on your own evening list?","options":[],"answer":"I can write books, pen, water and any other item I need for the next day.","explanation_fr":"La réponse doit présenter une courte liste d'objets utiles pour le lendemain."}]},
    {"day":5,"level":"A2","questions":[{"type":"mcq","question":"Where does Lina put her short list?","options":["Near her bag","Inside her homework","At her school","In her water bottle"],"answer":"Near her bag","explanation_fr":"Lina place la liste près de son sac."},{"type":"true_false","question":"The text says that our memory is perfect.","options":["True","False"],"answer":"False","explanation_fr":"Le texte affirme au contraire que notre mémoire n'est pas parfaite."},{"type":"mcq","question":"What can checking a list at the same time each day help build?","options":["A habit","Heavy traffic","A difficult problem","A new language immediately"],"answer":"A habit","explanation_fr":"Vérifier la liste au même moment chaque jour aide à créer une habitude."},{"type":"mcq","question":"How much should you change at once?","options":["One small action","Everything immediately","Only difficult things","Nothing under any circumstances"],"answer":"One small action","explanation_fr":"Le texte recommande une petite action plutôt qu'un changement total."},{"type":"open","question":"Describe one small problem and what you can do differently tomorrow.","options":[],"answer":"I sometimes forget my pen. This evening, I can put it in my bag and check my list.","explanation_fr":"La réponse doit relier un petit problème précis à une action concrète pour le lendemain."}]},
    {"day":5,"level":"B1","questions":[{"type":"mcq","question":"What could Nadia check before leaving home?","options":["The weather forecast","Other people's memories","The price of her course","The number of cars in town"],"answer":"The weather forecast","explanation_fr":"Nadia pouvait consulter les prévisions météo avant de partir."},{"type":"mcq","question":"How long did Nadia spend reviewing her day?","options":["Five minutes","One hour","All evening","Thirty seconds every Monday"],"answer":"Five minutes","explanation_fr":"Elle consacrait cinq minutes chaque soir à ce bilan."},{"type":"true_false","question":"Reflection made every day perfect for Nadia.","options":["True","False"],"answer":"False","explanation_fr":"Le texte dit clairement que la réflexion ne rendait pas chaque jour parfait."},{"type":"mcq","question":"What did Nadia understand better by Friday?","options":["Her habits","The whole transport system","Other people's goals","A new profession"],"answer":"Her habits","explanation_fr":"À la fin de la semaine, elle comprenait mieux ses habitudes."},{"type":"open","question":"What two things could you write in your own evening review?","options":[],"answer":"I can write one thing that went well and one thing I want to improve tomorrow.","explanation_fr":"La réponse doit reprendre les deux éléments du bilan quotidien proposé."}]},
    {"day":5,"level":"B2","questions":[{"type":"mcq","question":"What should you do after testing one change?","options":["Check the result","Assume it solved everything","Change five more things immediately","Ignore the remaining problem"],"answer":"Check the result","explanation_fr":"Après avoir testé un changement, il faut examiner son résultat."},{"type":"true_false","question":"Preparing your bag can remove traffic.","options":["True","False"],"answer":"False","explanation_fr":"Cette préparation fait gagner du temps mais ne supprime pas la circulation."},{"type":"mcq","question":"How does the text redefine discipline?","options":["Testing and adjusting a plan","Blaming yourself more strongly","Making a promise without action","Controlling every external event"],"answer":"Testing and adjusting a plan","explanation_fr":"La discipline devient un processus d'essai et d'ajustement."},{"type":"mcq","question":"What is the aim of the five minute review?","options":["Turn experience into practical knowledge","Analyse every mistake endlessly","Prove that you are perfect","Avoid all future difficulties"],"answer":"Turn experience into practical knowledge","explanation_fr":"Le but est de transformer l'expérience quotidienne en connaissances pratiques."},{"type":"open","question":"Describe a result that would tell you to adjust a plan further.","options":[],"answer":"If preparing my bag saves time but I still arrive late, I should also adjust my departure time.","explanation_fr":"La réponse doit montrer qu'un résultat insuffisant conduit à un nouvel ajustement."}]},
    {"day":5,"level":"C1","questions":[{"type":"true_false","question":"Effective reflection includes an honest assessment of external constraints.","options":["True","False"],"answer":"True","explanation_fr":"Le texte associe responsabilité personnelle et évaluation honnête des contraintes extérieures."},{"type":"mcq","question":"Which sequence best matches the suggested evening review?","options":["What happened, what influenced it, what adjustment is worth trying","Who is guilty, how to avoid responsibility, why change is impossible","What others did, why they are wrong, how to criticise them","What happened, why it always happens, why nothing can change"],"answer":"What happened, what influenced it, what adjustment is worth trying","explanation_fr":"Ces trois questions structurent le bilan du soir proposé."},{"type":"mcq","question":"What does deliberate adaptation require?","options":["Using evidence from experience to adjust behaviour","Repeating the same plan regardless of results","Eliminating every disruption before acting","Judging yourself after each mistake"],"answer":"Using evidence from experience to adjust behaviour","explanation_fr":"L'adaptation délibérée utilise l'expérience pour modifier consciemment l'action."},{"type":"mcq","question":"Which attitude does the text reject?","options":["Constant self criticism","Brief evening reflection","Personal responsibility","Recognition of external constraints"],"answer":"Constant self criticism","explanation_fr":"Le texte précise que l'objectif n'est ni l'autocritique constante ni le contrôle parfait."},{"type":"open","question":"How can reflection remain responsible without becoming self blame?","options":[],"answer":"I can identify my choices and the external conditions, then test one realistic adjustment instead of judging my whole character.","explanation_fr":"La réponse doit distinguer les choix personnels, les contraintes et l'ajustement expérimental."}]},
    {"day":6,"level":"A1","questions":[{"type":"mcq","question":"What do you put in your bag in the evening?","options":["Your books and a pen","Your shoes and dinner","A football and a guitar","Only your phone"],"answer":"Your books and a pen","explanation_fr":"Le texte conseille de mettre les livres et un stylo dans le sac."},{"type":"mcq","question":"When do you read three English words?","options":["After breakfast","Before midnight","During football","Only on Sunday"],"answer":"After breakfast","explanation_fr":"La lecture des trois mots se fait après le petit déjeuner."},{"type":"true_false","question":"You write the English words in a notebook.","options":["True","False"],"answer":"True","explanation_fr":"Le texte demande de dire les mots puis de les écrire dans un carnet."},{"type":"mcq","question":"How many actions should you start with?","options":["One small action","Ten difficult actions","Every possible action","No action"],"answer":"One small action","explanation_fr":"La conclusion recommande de commencer par une petite action."},{"type":"open","question":"Which small action can you repeat every day?","options":[],"answer":"I can prepare my bag every evening or read and write three English words after breakfast.","explanation_fr":"La réponse doit choisir une petite action quotidienne décrite dans le texte."}]}
  ]$content$::jsonb) as x(day integer, level public.rw_level, questions jsonb)
)
update public.rw_lessons as l
set questions = l.questions || extra.questions,
    status = 'published',
    published_at = coalesce(l.published_at, now()),
    rights_status = coalesce(l.rights_status, 'Texte original OpenDoorsClass')
from extra
join public.rw_weeks w on w.week_number = 3
join public.rw_sessions s on s.week_id = w.id and s.day_index = extra.day
where l.session_id = s.id
  and l.level = extra.level
  and l.status = 'draft'
  and jsonb_array_length(l.questions) = 5;

do $$
declare
  invalid_count integer;
begin
  select count(*) into invalid_count
  from public.rw_lessons l
  join public.rw_sessions s on s.id = l.session_id
  join public.rw_weeks w on w.id = s.week_id
  where w.week_number = 3
    and ((s.day_index in (4,5)) or (s.day_index = 6 and l.level = 'A1'))
    and (l.status <> 'published' or jsonb_array_length(l.questions) <> 10);
  if invalid_count <> 0 then
    raise exception 'Validation impossible: % leçons incomplètes', invalid_count;
  end if;
end $$;